SourceCode.Declaration:
class TFMMediaItem 
{
    private str name;
    private str base64;
    private str url;

}

Method.Source:
public str parmName(str _name = name)
{
    name = _name;
    return name;
}

public str parmBase64(str _base64 = base64)
{
    base64 = _base64;
    return base64;
}

/// <summary>
/// The url for the media. Only insert permanent URLs. Use the base64 for non-permanent URLs.
/// </summary>
public str parmURL(str _url = url)
{
    url = _url;
    return url;
}

/// <summary>
/// Helper method for the base64 string version usable for insertion in HTML img tags.
/// </summary>
/// <returns>a base64 str usable for insertion in HTML img tags.</returns>
public str getBase64ForHtml()
{
    return 'data:image/png;base64,' + base64;
}

/// <summary>
/// Helper method for getting the URL when present else using the Base64 version of the menu item.
/// </summary>
/// <returns>a String usable for insertion in HTML img tags.</returns>
public str getMediaForHtml()
{
    if(url)
    {
        return url;
    }
    return this.getBase64ForHtml();
}
